<?php
use EIPSI\StudyEngine\Longitudinal as L;use EIPSI\StudyEngine\Persistence as P;use EIPSI\StudyEngine\Runtime as R;use EIPSI\AssessmentEditor\Runtime as N;use EIPSI\AssessmentEditor\Definition as D;use EIPSI\StudyEngine\Contracts\Canonical;
function s2_version($prefix,$pages=2){
 $base=json_decode(file_get_contents(dirname(__DIR__).'/assessment-editor/functional-fixture.json'),true);$q=$base['elements'][0];$break=$base['elements'][3];$base['id']='AE_SEC2_'.bin2hex(random_bytes(8));$base['elements']=array();$base['flow']['pages']=array();$base['flow']['allow_back']=true;
 for($i=0;$i<$pages;$i++){if($i){$b=$break;$b['id']=$prefix.'_PAGE_'.$i;$base['elements'][]=$b;}$item=$q;$item['id']=$prefix.'_Q'.$i;$item['response_key']=$prefix.'_R'.$i;$item['properties']['variable_name']=$prefix.'_var'.$i;$item['properties']['required']=true;$base['elements'][]=$item;}
 $base=D::validate($base);$o=s2_owner();$o->store->install();$json=D::json($base);$v=array('id'=>'NV_SEC2_'.bin2hex(random_bytes(8)),'assessment_id'=>$base['id'],'author_revision'=>1,'definition_json'=>$json,'definition_hash'=>hash('sha256',$json),'state'=>'PUBLISHED','actor_id'=>1,'created_at'=>strtotime($GLOBALS['pf_now']));$o->store->transaction(fn()=>$o->store->insert('versions',$v));return array('row'=>$v,'definition'=>$base);
}
function s2_logic($kind=null,$future=false){
 $source=s2_version('SOURCE');$target=s2_version('TARGET');$d=pe_definition();$d['nodes']=array_values(array_filter($d['nodes'],static fn($n)=>$n['kind']==='BLOCK'));$sourceNode=null;
 foreach($d['nodes']as&$n){if($n['parent_id']===$d['id'])$n['children_strategy']='PARALLEL_AVAILABLE';if($n['completion_boundary']==='ASSESSMENT'){$n['metadata']=array('native_version_id'=>$source['row']['id'],'native_definition_hash'=>$source['row']['definition_hash'],'native_questions'=>s2_catalog($source['definition']));$sourceNode=$n;}}unset($n);
 $to=$sourceNode;$to['id']='E_SEC2_TARGET';$to['logical_id']=$to['id'];$to['position']++;$to['metadata']=array('native_version_id'=>$target['row']['id'],'native_definition_hash'=>$target['row']['definition_hash'],'native_questions'=>s2_catalog($target['definition']));if($future)$to['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'ELAPSED','seconds'=>3600));$d['nodes'][]=$to;
 foreach(array($sourceNode,$to)as$n){$json=Canonical::json(array('label'=>'Native','html'=>''));$id='C_'.$n['id'];$d['nodes'][]=array('kind'=>'CONTENT','id'=>$id,'version_id'=>$d['id'],'parent_id'=>$n['id'],'position'=>0,'type'=>'TEXT','content'=>array('content_id'=>$id,'version'=>1,'snapshot'=>$json,'sha256'=>hash('sha256',$json)),'durable_reference'=>null);}
 if($kind!==null)$d['protocol_metadata']['trajectory_conditions']=array(array('id'=>'SEC2_LOGIC','label'=>'Condición de prueba','source'=>array('assessment_id'=>$sourceNode['id'],'question_id'=>'SOURCE_Q0'),'event'=>'ANSWER','priority'=>1,'predicate'=>array('op'=>'EQ','reference'=>array('kind'=>'ANSWER','assessment_id'=>$sourceNode['id'],'question_id'=>'SOURCE_Q0'),'value'=>'go'),'actions'=>array(array('type'=>$kind,'target_id'=>$kind==='GO_QUESTION'?$sourceNode['id']:$to['id'],'question_id'=>$kind==='GO_QUESTION'?'SOURCE_Q1':'TARGET_Q1'))));
 $p=pe_publish('simple',false,L\Configuration::apply($d,array('verification_policy'=>'ALLOW_UNVERIFIED')));$GLOBALS['owned'][]=$d['study']['logical_id'];$f=pf_enroll($p);$id=s2_native($p,$f)['execution_id'];return array($p,$f,$id,$source,$target);
}
function s2_catalog($d){$out=array();$page=0;foreach($d['elements']as$e){if($e['type']==='page_break'){$page++;continue;}$out[]=array('id'=>$e['id'],'label'=>$e['id'],'response_key'=>$e['response_key'],'value_type'=>'STRING','options'=>array(),'page'=>$page,'randomization_id'=>null);}return$out;}
$cases['Paused Native keeps next back touched state and page recovery']=function(){list($p,$f,$id)=s2_logic();$o=s2_owner();pf_native_fixture_command($o,$id,'open');s2_state($p,'PAUSED');$next=pf_native_fixture_command($o,$id,'next',array('SOURCE_R0'=>'Primera respuesta'));pe_assert($next['page']===1,'Next rejected');$back=pf_native_fixture_command($o,$id,'back',array('SOURCE_R0'=>'Primera respuesta'));pe_assert($back['page']===0,'Back rejected');$again=pf_native_fixture_command($o,$id,'next',array('SOURCE_R0'=>'Primera respuesta'));$restored=$o->view($id);pe_assert($restored['page']===1&&$restored['session']['answers']['SOURCE_R0']==='Primera respuesta','Page recovery lost');pe_equal($again['metadata'],$restored['metadata'],'Metadata changed on recovery');};
$cases['Intra-assessment condition remains responsive during Pause']=function(){list($p,$f,$id)=s2_logic('GO_QUESTION');$o=s2_owner();pf_native_fixture_command($o,$id,'open');s2_state($p,'PAUSED');$r=pf_native_fixture_command($o,$id,'logic',array('SOURCE_R0'=>'go'));pe_assert($r['execution_id']===$id&&$r['page']===1&&$r['logical_entry_question']==='SOURCE_Q1'&&$r['logical_entry_page']===1,'Intra logic blocked or entry boundary lost');pe_assert(s2_native_count($f)===1,'Intra logic created another attempt');};
$cases['Cross-assessment jump reuses a target opened before Pause']=function(){list($p,$f,$id,$source,$target)=s2_logic('JUMP');$binding=s2_input($p,$f,'open')['binding'];foreach($f['view']['snapshot']['instances']as$i)if($i['definition_id']==='E_SEC2_TARGET')$binding['block_execution_id']=$i['id'];$existing=s2_owner()->studyAssignment($target['row']['id'],$binding);s2_state($p,'PAUSED');$r=pf_native_fixture_command(s2_owner(),$id,'logic',array('SOURCE_R0'=>'go'));pe_assert($r['execution_id']===$existing['execution_id']&&$r['logical_entry_question']==='TARGET_Q1','Existing target blocked');pe_assert(s2_native_count($f)===2,'Jump duplicated a Native attempt');};
$cases['Cross-assessment jump needing an unopened target waits for Resume']=function(){$saved=$GLOBALS['pf_now'];try{list($p,$f,$id)=s2_logic('JUMP',true);s2_state($p,'PAUSED');$r=pf_native_fixture_command(s2_owner(),$id,'logic',array('SOURCE_R0'=>'go'));pe_assert($r['state']==='LOGICAL_EXIT'&&s2_native_count($f)===1,'Created future attempt during Pause');$source=(new N\Store())->find('executions',$id);$view=pf_owner()->view($f['access']['execution_id']);pe_assert(!empty($view['snapshot']['logical_trajectory']['waits']),'Jump was discarded');s2_state($p,'ACTIVE');s2_time(gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+1));(new L\Worker(pf_db(),pe_vault(),pf_caps(),pf_clock()))->advanceBatch(100);$frame=pf_runtime()->handle($p['public'],$f['token']);$a=R\NativeBridge::offer($frame);pe_assert($a!==null&&$a['execution_id']!==$id&&s2_native_count($f)===2,'Jump did not resume');$entered=s2_owner()->view($a['execution_id']);pe_assert($entered['logical_entry_question']==='TARGET_Q1','Resume lost jump target');pe_assert((new N\Store())->find('executions',$id)['final_json']===$source['final_json'],'Resume rewrote historical answers');}finally{s2_time($saved);}};
